Predict the output of the following code and explain how `@property` protects instance invariants:

```python
class BoundedCounter:
    def __init__(self, limit: int):
        self.limit = limit
        self._val = 0

    @property
    def val(self) -> int:
        return self._val

    @val.setter
    def val(self, new_val: int) -> None:
        if new_val > self.limit:
            raise ValueError('Limit exceeded')
        self._val = new_val

c = BoundedCounter(10)
c.val = 5
print(c.val)
try:
    c.val = 15
except ValueError as e:
    print(f'Error: {e}')
```

